def scaled_dot_product_attention(Q, K, V):
    d_k = K.size(-1)
    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(d_k)
    weights = torch.softmax(scores, dim=-1)
    return torch.bmm(weights, V)

def cross_entropy_loss(logits, targets):
    log_probs = logits - torch.logsumexp(logits, dim=-1, keepdim=True)
    return -log_probs[torch.arange(targets.shape[0]), targets].mean()

class MyDropout(nn.Module):
    def __init__(self, p=0.5):
        super().__init__()
        self.p = p

    def forward(self, x):
        if not self.training or self.p == 0:
            return x
        mask = (torch.rand_like(x) > self.p).float()
        return x * mask / (1 - self.p)

class MyEmbedding(nn.Module):
    def __init__(self, num_embeddings, embedding_dim):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(num_embeddings, embedding_dim))

    def forward(self, indices):
        return self.weight[indices]

def flow_matching_loss(model_output, x0, x1, t):
    target_velocity = x1 - x0
    diff = model_output - target_velocity
    return (diff * diff).mean()

def clip_grad_norm(parameters, max_norm):
    parameters = [p for p in parameters if p.grad is not None]
    total_norm = torch.sqrt(sum(p.grad.norm() ** 2 for p in parameters))
    clip_coef = max_norm / (total_norm + 1e-6)
    if clip_coef < 1:
        for p in parameters:
            p.grad.mul_(clip_coef)
    return total_norm.item()

def graph_readout(X, batch, mode='mean'):
    import torch
    num_graphs = batch.max().item() + 1
    D = X.shape[1]
    if mode == 'sum':
        out = torch.zeros(num_graphs, D)
        out.index_add_(0, batch, X)
        return out
    elif mode == 'mean':
        out = torch.zeros(num_graphs, D)
        out.index_add_(0, batch, X)
        count = torch.zeros(num_graphs)
        count.index_add_(0, batch, torch.ones(batch.shape[0]))
        return out / count.unsqueeze(1)
    elif mode == 'max':
        out = torch.full((num_graphs, D), float('-inf'))
        for i in range(num_graphs):
            mask = batch == i
            out[i] = X[mask].max(dim=0).values
        return out
    else:
        raise ValueError(f"Unsupported mode: {mode}")

import torch


def per_token_logprobs(logits, input_ids):
    log_probs = torch.log_softmax(logits, dim=-1)
    return torch.gather(log_probs, dim=-1, index=input_ids.unsqueeze(-1)).squeeze(-1)

import torch


def response_token_mask(prompt_lens, total_lens, max_len):
    if prompt_lens.shape != total_lens.shape:
        raise ValueError(
            f"shape mismatch: {tuple(prompt_lens.shape)} vs {tuple(total_lens.shape)}"
        )
    if not isinstance(max_len, int) or max_len <= 0:
        raise ValueError(f"max_len must be a positive integer, got {max_len!r}")
    if (prompt_lens < 0).any() or (total_lens < prompt_lens).any() or (total_lens > max_len).any():
        raise ValueError("every row must satisfy 0 <= prompt_lens <= total_lens <= max_len")
    positions = torch.arange(max_len, device=prompt_lens.device).unsqueeze(0)
    return (positions >= prompt_lens.unsqueeze(-1)) & (positions < total_lens.unsqueeze(-1))

def my_softmax(x: torch.Tensor, dim: int = -1) -> torch.Tensor:
    x_max = x.max(dim=dim, keepdim=True).values
    e_x = torch.exp(x - x_max)
    return e_x / e_x.sum(dim=dim, keepdim=True)

import torch.utils.checkpoint as cp

def checkpoint_sequential(fns, x):
    for fn in fns:
        x = cp.checkpoint(fn, x, use_reentrant=False)
    return x

class MyAdam:
    def __init__(self, params, lr=1e-3, betas=(0.9, 0.999), eps=1e-8):
        self.params = list(params)
        self.lr = lr
        self.beta1, self.beta2 = betas
        self.eps = eps
        self.t = 0
        self.m = [torch.zeros_like(p) for p in self.params]
        self.v = [torch.zeros_like(p) for p in self.params]

    def step(self):
        self.t += 1
        with torch.no_grad():
            for i, p in enumerate(self.params):
                if p.grad is None:
                    continue
                self.m[i] = self.beta1 * self.m[i] + (1 - self.beta1) * p.grad
                self.v[i] = self.beta2 * self.v[i] + (1 - self.beta2) * p.grad ** 2
                m_hat = self.m[i] / (1 - self.beta1 ** self.t)
                v_hat = self.v[i] / (1 - self.beta2 ** self.t)
                p -= self.lr * m_hat / (torch.sqrt(v_hat) + self.eps)

    def zero_grad(self):
        for p in self.params:
            if p.grad is not None:
                p.grad.zero_()

def beam_search(log_prob_fn, start_token, max_len, beam_width, eos_token):
    beams = [(0.0, [start_token])]
    completed = []
    for _ in range(max_len):
        candidates = []
        for score, seq in beams:
            if seq[-1] == eos_token:
                completed.append((score, seq))
                continue
            log_probs = log_prob_fn(torch.tensor(seq))
            topk_lp, topk_idx = log_probs.topk(beam_width)
            for j in range(beam_width):
                candidates.append((score + topk_lp[j].item(), seq + [topk_idx[j].item()]))
        if not candidates:
            break
        candidates.sort(key=lambda x: x[0], reverse=True)
        beams = candidates[:beam_width]
    all_seqs = completed + beams
    all_seqs.sort(key=lambda x: x[0], reverse=True)
    return all_seqs[0][1]

def cosine_lr_schedule(step, total_steps, warmup_steps, max_lr, min_lr=0.0):
    if step < warmup_steps:
        return max_lr * step / warmup_steps
    if step >= total_steps:
        return min_lr
    progress = (step - warmup_steps) / (total_steps - warmup_steps)
    return min_lr + 0.5 * (max_lr - min_lr) * (1.0 + math.cos(math.pi * progress))

import torch


def dapo_dynamic_sampling(rewards, group_size, tol=0.0):
    if not isinstance(group_size, int) or group_size <= 0:
        raise ValueError(f"group_size must be a positive integer, got {group_size!r}")
    if rewards.numel() % group_size != 0:
        raise ValueError(
            f"group_size {group_size} does not divide {rewards.numel()} rewards"
        )
    if tol < 0:
        raise ValueError(f"tol must be non-negative, got {tol}")

    grouped = rewards.reshape(-1, group_size)
    spread = grouped.max(dim=-1).values - grouped.min(dim=-1).values
    keep = spread > tol
    return keep.repeat_interleave(group_size)

def sparse_ffn_forward(x, expert_indices, expert_weights, experts):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("route tensors must align with tokens and indices must be long")
    if not experts:
        raise ValueError("at least one expert is required")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(experts)):
        raise ValueError("expert index out of range")
    routes = [[] for _ in experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            routes[int(expert_indices[token, slot])].append((token, slot))
    output = torch.zeros_like(x)
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        output.index_add_(0, token_ids, expert_output * route_weights)
    return output

def dpo_loss(policy_chosen_logps, policy_rejected_logps,
             ref_chosen_logps, ref_rejected_logps, beta=0.1):
    chosen_rewards = beta * (policy_chosen_logps - ref_chosen_logps)
    rejected_rewards = beta * (policy_rejected_logps - ref_rejected_logps)
    diff = chosen_rewards - rejected_rewards
    return -torch.log(torch.sigmoid(diff)).mean()

import torch


def group_relative_advantage(rewards, group_size, eps=1e-4):
    if not isinstance(group_size, int) or group_size <= 0:
        raise ValueError(f"group_size must be a positive integer, got {group_size!r}")
    if rewards.numel() % group_size != 0:
        raise ValueError(
            f"group_size {group_size} does not divide {rewards.numel()} rewards"
        )
    grouped = rewards.reshape(-1, group_size)
    mean = grouped.mean(dim=-1, keepdim=True)
    std = grouped.std(dim=-1, unbiased=False, keepdim=True)
    return ((grouped - mean) / (std + eps)).reshape(-1)

import torch


def gspo_sequence_ratio(logprobs, old_logprobs, mask):
    shapes = (logprobs.shape, old_logprobs.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")

    keep = mask.to(logprobs.dtype)
    log_ratio = (logprobs - old_logprobs) * keep
    count = keep.sum(dim=-1)
    mean_log_ratio = log_ratio.sum(dim=-1) / count.clamp(min=1.0)
    return torch.exp(mean_log_ratio)

def hybrid_attention_schedule(Q, K, V, layer_index, window_size, global_every):
    if Q.ndim != 3 or K.ndim != 3 or V.ndim != 3:
        raise ValueError("Q, K, and V must be rank-3 tensors")
    if Q.shape[:2] != K.shape[:2] or Q.shape[:2] != V.shape[:2] or Q.shape[-1] != K.shape[-1]:
        raise ValueError("Q, K, and V batch/sequence shapes and Q/K head dimensions must match")
    if Q.shape[0] == 0 or Q.shape[1] == 0 or Q.shape[-1] == 0 or V.shape[-1] == 0:
        raise ValueError("batch, sequence, head_dim, and value_dim must be non-empty")
    if layer_index < 0 or window_size < 0 or global_every < 1:
        raise ValueError("layer_index/window_size must be non-negative and global_every positive")

    scores = torch.bmm(Q, K.transpose(1, 2)) / math.sqrt(Q.shape[-1])
    sequence = Q.shape[1]
    query_position = torch.arange(sequence, device=Q.device).unsqueeze(1)
    key_position = torch.arange(sequence, device=Q.device).unsqueeze(0)
    allowed = key_position <= query_position
    if (layer_index + 1) % global_every != 0:
        allowed = allowed & (key_position >= query_position - window_size)
    scores = scores.masked_fill(~allowed.unsqueeze(0), float("-inf"))
    return torch.bmm(torch.softmax(scores, dim=-1), V)

import torch


def k3_kl_penalty(logprobs, ref_logprobs):
    if logprobs.shape != ref_logprobs.shape:
        raise ValueError(
            f"shape mismatch: {tuple(logprobs.shape)} vs {tuple(ref_logprobs.shape)}"
        )
    log_ratio = ref_logprobs - logprobs
    return torch.exp(log_ratio) - log_ratio - 1.0

def my_layer_norm(x, gamma, beta, eps=1e-5):
    mean = x.mean(dim=-1, keepdim=True)
    var = x.var(dim=-1, keepdim=True, unbiased=False)
    x_norm = (x - mean) / torch.sqrt(var + eps)
    return gamma * x_norm + beta

class SimpleLinear:
    def __init__(self, in_features: int, out_features: int):
        self.weight = torch.randn(out_features, in_features) * (1 / math.sqrt(in_features))
        self.weight.requires_grad_(True)
        self.bias = torch.zeros(out_features, requires_grad=True)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return x @ self.weight.T + self.bias

class SwiGLUMLP(nn.Module):
    def __init__(self, d_model, d_ff):
        super().__init__()
        self.gate_proj = nn.Linear(d_model, d_ff)
        self.up_proj = nn.Linear(d_model, d_ff)
        self.down_proj = nn.Linear(d_ff, d_model)

    def forward(self, x):
        gate = self.gate_proj(x)
        silu_gate = gate * torch.sigmoid(gate)
        return self.down_proj(silu_gate * self.up_proj(x))

def noisy_topk_route(clean_logits, noise, noise_std, k):
    if clean_logits.ndim != 2 or not isinstance(noise, torch.Tensor) or noise.shape != clean_logits.shape:
        raise ValueError("clean_logits and noise must be matching (tokens, num_experts) tensors")
    if not clean_logits.is_floating_point():
        raise ValueError("clean_logits must be floating point")
    num_experts = clean_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or k < 1 or k > num_experts:
        raise ValueError("k must be an integer in [1, num_experts]")
    if noise_std < 0:
        raise ValueError("noise_std must be non-negative")
    noisy = clean_logits + noise_std * noise
    probs = torch.softmax(noisy, dim=-1)
    weights, indices = torch.topk(probs, k, dim=-1)
    weights = weights / weights.sum(-1, keepdim=True)
    return indices, weights

def router_z_loss(router_logits):
    if not isinstance(router_logits, torch.Tensor) or router_logits.ndim != 2:
        raise ValueError("router_logits must be a (tokens, num_experts) tensor")
    if not router_logits.is_floating_point():
        raise ValueError("router_logits must be floating point")
    log_partition = torch.logsumexp(router_logits, dim=-1)
    return log_partition.square().mean()

def shared_routed_moe(x, expert_indices, expert_weights, routed_experts, shared_experts):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and routed route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("routed route tensors must align with tokens and indices must be long")
    if not routed_experts:
        raise ValueError("at least one routed expert is required")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(routed_experts)):
        raise ValueError("routed expert index out of range")
    routed_out = torch.zeros_like(x)
    routes = [[] for _ in routed_experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            routes[int(expert_indices[token, slot])].append((token, slot))
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = routed_experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        routed_out.index_add_(0, token_ids, expert_output * route_weights)
    shared_out = torch.zeros_like(x)
    for shared in shared_experts:
        shared_out = shared_out + shared(x)
    return routed_out + shared_out

def moe_topk_router(router_logits, k):
    if router_logits.ndim != 2:
        raise ValueError("router_logits must have shape (tokens, experts)")
    num_experts = router_logits.shape[-1]
    if not isinstance(k, int) or isinstance(k, bool) or not 1 <= k <= num_experts:
        raise ValueError("k must select between one and all experts")
    probabilities = torch.softmax(router_logits, dim=-1)
    weights, indices = torch.topk(probabilities, k, dim=-1)
    weights = weights / weights.sum(dim=-1, keepdim=True)
    return indices, weights

class PolicyDecision:
    def __init__(self, action, context, reasons):
        from copy import deepcopy
        self.action = action
        self.context = deepcopy(context)
        self.reasons = list(reasons)


class PolicyEngine:
    def __init__(self, policies):
        if not isinstance(policies, (list, tuple)):
            raise TypeError("policies must be an ordered sequence")
        names = []
        for policy in policies:
            name = getattr(policy, "name", None)
            if not isinstance(name, str) or not name or not callable(getattr(policy, "evaluate", None)):
                raise TypeError("each policy needs a name and evaluate method")
            names.append(name)
        if len(names) != len(set(names)):
            raise ValueError("policy names must be unique")
        self._policies = tuple(policies)

    def evaluate(self, context):
        from copy import deepcopy
        from torch_judge.harness import HarnessFailure
        from torch_judge.harness.agents.protocol import copy_json

        working = copy_json(context, field="policy context JSON")
        if not isinstance(working, dict):
            raise TypeError("policy context must be a dictionary")
        transformed = False
        reasons = []
        for policy in self._policies:
            try:
                result = policy.evaluate(deepcopy(working))
            except HarnessFailure:
                raise
            except Exception as error:
                return PolicyDecision(
                    "deny",
                    working,
                    [f"{policy.name}: policy_error: {type(error).__name__}: {error}"],
                )
            valid = isinstance(result, dict)
            action = result.get("action") if valid else None
            reason = result.get("reason") if valid else None
            changes = result.get("changes") if valid else None
            if (
                action not in {"allow", "deny", "transform"}
                or (reason is not None and not isinstance(reason, str))
                or (action == "transform" and not isinstance(changes, dict))
                or (action != "transform" and changes is not None)
            ):
                return PolicyDecision(
                    "deny", working, [f"{policy.name}: invalid_policy_result"]
                )
            if action == "deny":
                return PolicyDecision(
                    "deny", working, [f"{policy.name}: {reason or 'denied'}"]
                )
            if action == "transform":
                try:
                    changes = copy_json(changes, field="policy changes JSON")
                except Exception:
                    return PolicyDecision(
                        "deny", working, [f"{policy.name}: invalid_policy_result"]
                    )
                working.update(changes)
                transformed = True
                if reason:
                    reasons.append(f"{policy.name}: {reason}")
        return PolicyDecision("transform" if transformed else "allow", working, reasons)

import torch


def ppo_value_loss(values, old_values, returns, mask, clip_eps=0.2):
    shapes = (values.shape, old_values.shape, returns.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")
    if clip_eps <= 0:
        raise ValueError(f"clip_eps must be positive, got {clip_eps}")

    keep = mask.to(values.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=values.dtype, device=values.device)

    clipped_value = old_values + (values - old_values).clamp(-clip_eps, clip_eps)
    unclipped_error = (values - returns) ** 2
    clipped_error = (clipped_value - returns) ** 2
    per_token = 0.5 * torch.max(unclipped_error, clipped_error)
    return (per_token * keep).sum() / denominator

def qk_norm(q, k, eps=1e-6):
    def normalize(x):
        work = x.float() if x.dtype in (torch.float16, torch.bfloat16) else x
        inverse_rms = torch.rsqrt(work.square().mean(dim=-1, keepdim=True) + eps)
        return (work * inverse_rms).to(x.dtype)

    return normalize(q), normalize(k)

def rms_norm(x, weight, eps=1e-6):
    rms = torch.sqrt(x.pow(2).mean(dim=-1, keepdim=True) + eps)
    return x / rms * weight

def apply_rope(q, k):
    B, S, D = q.shape
    pos = torch.arange(S, device=q.device).unsqueeze(1).float()
    dim = torch.arange(0, D, 2, device=q.device).float()
    freqs = 1.0 / (10000.0 ** (dim / D))
    angles = pos * freqs
    cos_a = torch.cos(angles)
    sin_a = torch.sin(angles)

    def rotate(x):
        x1, x2 = x[..., 0::2], x[..., 1::2]
        return torch.stack([x1 * cos_a - x2 * sin_a,
                            x1 * sin_a + x2 * cos_a], dim=-1).flatten(-2)

    return rotate(q), rotate(k)

class ToolRegistry:
    _TYPE_NAMES = {
        str: "string", int: "integer", float: "number",
        bool: "boolean", list: "array", dict: "object",
    }

    def __init__(self):
        self._tools = {}

    def register(self, tool):
        if not isinstance(tool.name, str) or not tool.name:
            raise ValueError("tool name must be non-empty")
        if tool.name in self._tools:
            raise ValueError(f"duplicate tool: {tool.name}")
        if not isinstance(tool.description, str) or not tool.description:
            raise ValueError("tool description must be non-empty")
        if not isinstance(tool.argument_schema, dict):
            raise TypeError("argument schema must be a dictionary")
        if any(not isinstance(name, str) or declared not in self._TYPE_NAMES
               for name, declared in tool.argument_schema.items()):
            raise TypeError("argument schema contains an unsupported entry")
        self._tools[tool.name] = tool

    def describe(self):
        return [
            {
                "name": tool.name,
                "description": tool.description,
                "parameters": {
                    name: self._TYPE_NAMES[declared]
                    for name, declared in tool.argument_schema.items()
                },
            }
            for tool in self._tools.values()
        ]

    def invoke(self, name, arguments, idempotency_key=None):
        if name not in self._tools:
            raise KeyError(f"unknown tool: {name}")
        if not isinstance(arguments, dict):
            raise TypeError("arguments must be a dictionary")
        tool = self._tools[name]
        if set(arguments) != set(tool.argument_schema):
            raise ValueError("argument names do not match the schema")
        for argument, declared in tool.argument_schema.items():
            if type(arguments[argument]) is not declared:
                raise TypeError(f"invalid type for {argument}")
        return tool.invoke(arguments, idempotency_key=idempotency_key)

class PatchEmbedding(nn.Module):
    def __init__(self, img_size, patch_size, in_channels, embed_dim):
        super().__init__()
        self.patch_size = patch_size
        self.num_patches = (img_size // patch_size) ** 2
        self.proj = nn.Linear(in_channels * patch_size * patch_size, embed_dim)

    def forward(self, x):
        B, C, H, W = x.shape
        p = self.patch_size
        n_h, n_w = H // p, W // p
        x = x.reshape(B, C, n_h, p, n_w, p)
        x = x.permute(0, 2, 4, 1, 3, 5).reshape(B, n_h * n_w, C * p * p)
        return self.proj(x)

class ApprovalRequest:
    def __init__(self, digest, action, identity, expires_at):
        from copy import deepcopy
        self.digest = digest
        self.action = deepcopy(action)
        self.identity = identity
        self.expires_at = expires_at


