class DeniedAction:
    def __init__(self, reason):
        self.reason = reason


class ApprovalGate:
    def __init__(self, approval_required, clock, ttl=60):
        from math import isfinite
        if not isinstance(approval_required, set) or not all(
            isinstance(item, str) and item for item in approval_required
        ):
            raise TypeError("approval_required must be a set of capability strings")
        if (isinstance(ttl, bool) or not isinstance(ttl, (int, float))
                or not isfinite(float(ttl)) or ttl <= 0):
            raise ValueError("ttl must be a positive finite number")
        self._approval_required = frozenset(approval_required)
        self._clock = clock
        self._ttl = float(ttl)
        self._requests = {}
        self._grants = {}
        self._sequence = 0

    def _validated(self, action, capabilities, provenance):
        from copy import deepcopy
        from torch_judge.harness.agents.protocol import copy_json
        try:
            copied = copy_json(action, field="approval action JSON")
            source = copy_json(provenance, field="approval provenance JSON")
        except Exception:
            return DeniedAction("malformed_request")
        if not isinstance(copied, dict) or not isinstance(source, dict):
            return DeniedAction("malformed_request")
        if not isinstance(capabilities, set) or not all(
            isinstance(item, str) and item for item in capabilities
        ):
            return DeniedAction("malformed_capabilities")
        required = ("tool", "capability", "actor", "arguments")
        if (any(not isinstance(copied.get(key), str) or not copied[key]
                for key in required[:3]) or not isinstance(copied.get("arguments"), dict)):
            return DeniedAction("malformed_request")
        if (not isinstance(source.get("identity"), str) or not source["identity"]
                or not isinstance(source.get("source"), str) or not source["source"]
                or source.get("trust") not in {"trusted", "untrusted"}):
            return DeniedAction("malformed_provenance")
        if source["identity"] != copied["actor"]:
            return DeniedAction("identity_mismatch")
        if copied["capability"] not in capabilities:
            return DeniedAction("capability_not_granted")
        return deepcopy(copied), deepcopy(source)

    @staticmethod
    def _digest(action, provenance):
        import hashlib
        import json
        bound_action = {key: value for key, value in action.items() if key != "approval_token"}
        bound = {
            "action": bound_action,
            "identity": provenance["identity"],
            "source": provenance["source"],
        }
        encoded = json.dumps(bound, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()

    def classify(self, action, capabilities, provenance):
        checked = self._validated(action, capabilities, provenance)
        if isinstance(checked, DeniedAction):
            return checked
        copied, source = checked
        capability = copied["capability"]
        clean_action = {key: value for key, value in copied.items() if key != "approval_token"}
        if capability not in self._approval_required:
            return ApprovedAction(clean_action)
        if source["trust"] != "trusted":
            return DeniedAction("untrusted_provenance")
        digest = self._digest(copied, source)
        token = copied.get("approval_token")
        if token is None:
            request = ApprovalRequest(
                digest, clean_action, source["identity"], self._clock.now() + self._ttl
            )
            self._requests[id(request)] = {
                "digest": digest,
                "identity": source["identity"],
                "expires_at": request.expires_at,
                "approved": False,
            }
            return request
        grant = self._grants.get(token) if isinstance(token, str) else None
        if grant is None:
            return DeniedAction("approval_invalid")
        if grant["consumed"]:
            return DeniedAction("approval_replayed")
        if grant["digest"] != digest or grant["identity"] != source["identity"]:
            return DeniedAction("approval_mismatch")
        if self._clock.now() >= grant["expires_at"]:
            return DeniedAction("approval_expired")
        grant["consumed"] = True
        return ApprovedAction(clean_action)

    def approve(self, request, approver):
        import hashlib
        if not isinstance(request, ApprovalRequest) or id(request) not in self._requests:
            raise TypeError("request must originate from this gate")
        if (not isinstance(approver, dict)
                or not isinstance(approver.get("identity"), str) or not approver["identity"]
                or approver.get("trust") != "trusted"):
            raise ValueError("approver must be a trusted named identity")
        stored = self._requests[id(request)]
        if stored["approved"]:
            raise ValueError("approval request was already approved")
        stored["approved"] = True
        self._sequence += 1
        token = hashlib.sha256(
            f"{stored['digest']}:{approver['identity']}:{self._sequence}".encode("utf-8")
        ).hexdigest()
        self._grants[token] = {
            "digest": stored["digest"],
            "identity": stored["identity"],
            "expires_at": stored["expires_at"],
            "consumed": False,
        }
        return token

class SimpleBPE:
    def __init__(self):
        self.merges = []

    def train(self, corpus, num_merges):
        vocab = {}
        for word in corpus:
            symbols = tuple(word) + ('</w>',)
            vocab[symbols] = vocab.get(symbols, 0) + 1
        self.merges = []
        for _ in range(num_merges):
            pairs = {}
            for word, freq in vocab.items():
                for i in range(len(word) - 1):
                    pair = (word[i], word[i + 1])
                    pairs[pair] = pairs.get(pair, 0) + freq
            if not pairs:
                break
            best = max(pairs, key=pairs.get)
            self.merges.append(best)
            new_vocab = {}
            for word, freq in vocab.items():
                new_word = []
                i = 0
                while i < len(word):
                    if i < len(word) - 1 and (word[i], word[i + 1]) == best:
                        new_word.append(word[i] + word[i + 1])
                        i += 2
                    else:
                        new_word.append(word[i])
                        i += 1
                new_vocab[tuple(new_word)] = freq
            vocab = new_vocab

    def encode(self, text):
        all_tokens = []
        for word in text.split():
            symbols = list(word) + ['</w>']
            for a, b in self.merges:
                i = 0
                while i < len(symbols) - 1:
                    if symbols[i] == a and symbols[i + 1] == b:
                        symbols = symbols[:i] + [a + b] + symbols[i + 2:]
                    else:
                        i += 1
            all_tokens.extend(symbols)
        return all_tokens

def budgeted_agent_loop(model, registry, messages, limits, retry_policy, clock, trace):
    from copy import deepcopy
    from math import isfinite
    from torch_judge.harness import HarnessFailure
    from torch_judge.harness.agents import (AgentResult, PermanentModelError,
        PermanentToolError, RetryableModelError, RetryableToolError)
    from torch_judge.harness.agents.protocol import copy_json

    run_id = correlation_id = "agent-run"
    start = clock.now()
    state = deepcopy(messages)
    iterations = tool_calls = tokens = 0
    cost = 0.0

    required = ("max_iterations", "max_tool_calls", "max_tokens", "max_time", "max_cost")
    if any(name not in limits for name in required):
        raise ValueError("limits are incomplete")
    if any(isinstance(limits[name], bool) or not isinstance(limits[name], (int, float))
           or not isfinite(float(limits[name])) or limits[name] < 0 for name in required):
        raise ValueError("limits must be non-negative finite numbers")
    max_attempts = retry_policy.get("max_attempts")
    base_delay = retry_policy.get("base_delay")
    if not isinstance(max_attempts, int) or isinstance(max_attempts, bool) or max_attempts < 1:
        raise ValueError("max_attempts must be a positive integer")
    if isinstance(base_delay, bool) or not isinstance(base_delay, (int, float)) or base_delay < 0:
        raise ValueError("base_delay must be non-negative")

    def elapsed():
        return clock.now() - start

    def cancelled():
        value = limits.get("cancelled", False)
        return bool(value() if callable(value) else value)

    terminal_events = {
        "completed": "run.completed", "failed": "run.failed",
        "budget_exceeded": "run.budget_exceeded", "cancelled": "run.cancelled",
    }

    def finish(status, content=None, failure=None):
        trace.emit(terminal_events[status], clock.now(), run_id, correlation_id,
                   {} if failure is None else {"failure": failure})
        return AgentResult(status, content, state, iterations, tool_calls, tokens,
                           cost, elapsed(), failure)

    def budget_failure(limit):
        return finish("budget_exceeded", failure={"type": "budget", "limit": limit})

    trace.emit("run.started", clock.now(), run_id, correlation_id, {})
    while True:
        if cancelled():
            return finish("cancelled", failure={"type": "cancelled"})
        if elapsed() > limits["max_time"]:
            return budget_failure("time")
        if iterations >= limits["max_iterations"]:
            return budget_failure("iterations")

        for model_attempt in range(1, max_attempts + 1):
            if cancelled():
                return finish("cancelled", failure={"type": "cancelled"})
            if elapsed() > limits["max_time"]:
                return budget_failure("time")
            if iterations >= limits["max_iterations"]:
                return budget_failure("iterations")
            iterations += 1
            try:
                response = model.call(deepcopy(state))
                trace.emit("model.called", clock.now(), run_id, correlation_id,
                           {"iteration": iterations, "attempt": model_attempt})
                break
            except HarnessFailure:
                raise
            except PermanentModelError as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "permanent"})
                return finish("failed", failure={"type": "permanent_model_failure",
                                                  "message": str(error)})
            except (RetryableModelError, TimeoutError) as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "retryable"})
                if model_attempt == max_attempts:
                    return finish("failed", failure={"type": "model_retry_exhausted",
                                                      "attempts": model_attempt,
                                                      "message": str(error)})
                delay = (error.retry_after if isinstance(error, RetryableModelError)
                         and error.retry_after is not None
                         else base_delay * 2 ** (model_attempt - 1))
                if elapsed() + delay > limits["max_time"]:
                    return budget_failure("time")
                trace.emit("model.retry", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "delay": delay})
                clock.sleep(delay)
            except Exception as error:
                trace.emit("model.failed", clock.now(), run_id, correlation_id,
                           {"attempt": model_attempt, "type": "unexpected",
                            "error_type": type(error).__name__})
                return finish("failed", failure={"type": "model_execution_failure",
                                                  "error_type": type(error).__name__,
                                                  "message": str(error)})
        try:
            if not isinstance(response, dict):
                raise ValueError
            usage = response.get("usage")
            used_tokens = usage.get("tokens") if isinstance(usage, dict) else None
            used_cost = usage.get("cost") if isinstance(usage, dict) else None
            if (not isinstance(used_tokens, int) or isinstance(used_tokens, bool)
                    or used_tokens < 0):
                raise ValueError
            if (not isinstance(used_cost, (int, float)) or isinstance(used_cost, bool)
                    or not isfinite(float(used_cost)) or used_cost < 0):
                raise ValueError
        except (AttributeError, ValueError):
            return finish("failed", failure={"type": "malformed_model_response"})
        tokens += used_tokens
        cost += float(used_cost)
        if tokens > limits["max_tokens"]:
            return budget_failure("tokens")
        if cost > limits["max_cost"]:
            return budget_failure("cost")
        if elapsed() > limits["max_time"]:
            return budget_failure("time")

        response_type = response.get("type")
        if response_type == "final":
            if not isinstance(response.get("content"), str):
                return finish("failed", failure={"type": "malformed_model_response"})
            return finish("completed", content=response["content"])
        if response_type != "tool_call":
            return finish("failed", failure={"type": "malformed_model_response"})
        call_id = response.get("call_id")
        name = response.get("name")
        arguments = response.get("arguments")
        idempotency_key = response.get("idempotency_key", None)
        if (not isinstance(call_id, str) or not call_id
                or not isinstance(name, str) or not name
                or not isinstance(arguments, dict)
                or (idempotency_key is not None
                    and (not isinstance(idempotency_key, str) or not idempotency_key))):
            return finish("failed", failure={"type": "malformed_model_response"})
        idempotency_key = idempotency_key or call_id

        for attempt in range(1, max_attempts + 1):
            if cancelled():
                return finish("cancelled", failure={"type": "cancelled"})
            if tool_calls >= limits["max_tool_calls"]:
                return budget_failure("tool_calls")
            if elapsed() > limits["max_time"]:
                return budget_failure("time")
            tool_calls += 1
            trace.emit("tool.started", clock.now(), run_id, correlation_id,
                       {"tool": name, "call_id": call_id, "attempt": attempt})
            try:
                tool_result = registry.invoke(name, deepcopy(arguments), idempotency_key)
                try:
                    tool_result = copy_json(tool_result, field="tool result JSON")
                except Exception:
                    trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                               {"tool": name, "type": "malformed_tool_result"})
                    return finish("failed", failure={"type": "malformed_tool_result", "tool": name})
                state.append({"role": "tool", "tool_call_id": call_id,
                              "name": name, "content": tool_result})
                trace.emit("tool.completed", clock.now(), run_id, correlation_id,
                           {"tool": name, "call_id": call_id, "attempt": attempt})
                break
            except HarnessFailure:
                raise
            except PermanentToolError as error:
                trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                           {"tool": name, "type": "permanent", "attempt": attempt})
                return finish("failed", failure={"type": "permanent_tool_failure",
                                                  "tool": name, "message": str(error)})
            except RetryableToolError as error:
                if attempt == max_attempts:
                    trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                               {"tool": name, "type": "retry_exhausted", "attempt": attempt})
                    return finish("failed", failure={"type": "retry_exhausted", "tool": name,
                                                      "attempts": attempt, "message": str(error)})
                delay = error.retry_after if error.retry_after is not None else base_delay * 2 ** (attempt - 1)
                if elapsed() + delay > limits["max_time"]:
                    return budget_failure("time")
                trace.emit("tool.retry", clock.now(), run_id, correlation_id,
                           {"tool": name, "call_id": call_id, "attempt": attempt, "delay": delay})
                clock.sleep(delay)
            except Exception as error:
                trace.emit("tool.failed", clock.now(), run_id, correlation_id,
                           {"tool": name, "type": "unexpected", "attempt": attempt,
                            "error_type": type(error).__name__})
                return finish("failed", failure={"type": "tool_execution_failure",
                                                  "tool": name,
                                                  "error_type": type(error).__name__,
                                                  "message": str(error)})

import torch


def gae_advantage(rewards, values, dones, gamma=0.99, lam=0.95):
    if rewards.shape != dones.shape:
        raise ValueError(
            f"rewards {tuple(rewards.shape)} and dones {tuple(dones.shape)} must match"
        )
    horizon = rewards.shape[-1]
    if values.shape[:-1] != rewards.shape[:-1] or values.shape[-1] != horizon + 1:
        raise ValueError(
            f"values {tuple(values.shape)} must have exactly one more column than "
            f"rewards {tuple(rewards.shape)}"
        )
    if not 0.0 <= gamma <= 1.0:
        raise ValueError(f"gamma must lie in [0, 1], got {gamma}")
    if not 0.0 <= lam <= 1.0:
        raise ValueError(f"lam must lie in [0, 1], got {lam}")

    not_done = 1.0 - dones.to(rewards.dtype)
    deltas = rewards + gamma * values[..., 1:] * not_done - values[..., :-1]

    advantages = torch.zeros_like(rewards)
    running = torch.zeros_like(rewards[..., 0])
    for t in reversed(range(horizon)):
        running = deltas[..., t] + gamma * lam * not_done[..., t] * running
        advantages[..., t] = running
    return advantages

import torch


def grpo_token_loss(logprobs, ref_logprobs, advantages, mask, beta=0.04):
    if logprobs.shape != ref_logprobs.shape or logprobs.shape != mask.shape:
        raise ValueError(
            f"logprobs {tuple(logprobs.shape)}, ref_logprobs {tuple(ref_logprobs.shape)} "
            f"and mask {tuple(mask.shape)} must share a shape"
        )
    if advantages.shape != logprobs.shape[:1]:
        raise ValueError(
            f"advantages {tuple(advantages.shape)} must have one entry per row of "
            f"{tuple(logprobs.shape)}"
        )
    if beta < 0:
        raise ValueError(f"beta must be non-negative, got {beta}")

    keep = mask.to(logprobs.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=logprobs.dtype, device=logprobs.device)

    log_ratio = ref_logprobs - logprobs
    kl = torch.exp(log_ratio) - log_ratio - 1.0
    objective = advantages.unsqueeze(-1) * logprobs - beta * kl
    return -(objective * keep).sum() / denominator

class GuardedResult:
    def __init__(self, status, output=None, failure=None, audit_records=None, pending_approval=None):
        from copy import deepcopy
        self.status = status
        self.output = deepcopy(output)
        self.failure = deepcopy(failure)
        self.audit_records = deepcopy(audit_records or [])
        self.pending_approval = pending_approval


def guarded_runtime(runtime, policy_engine, approval_gate, redactor, audit_sink, request):
    import hashlib
    import json
    from copy import deepcopy
    from math import isfinite
    from torch_judge.harness import HarnessFailure
    from torch_judge.harness.agents.protocol import copy_json

    class AuditFailure(Exception):
        def __init__(self, error): self.error = error

    class RedactionFailure(Exception):
        def __init__(self, error): self.error = error

    if not isinstance(request, dict):
        raise ValueError("request must be a dictionary")
    run_id = request.get("run_id")
    input_value = request.get("input")
    capabilities = request.get("capabilities")
    max_depth = request.get("max_delegation_depth")
    max_steps = request.get("max_steps")
    if not isinstance(run_id, str) or not run_id:
        raise ValueError("run_id must be non-empty")
    if not isinstance(capabilities, list) or not all(
        isinstance(item, str) and item for item in capabilities
    ) or len(capabilities) != len(set(capabilities)):
        raise ValueError("capabilities must be unique strings")
    if not isinstance(max_depth, int) or isinstance(max_depth, bool) or max_depth < 0:
        raise ValueError("max_delegation_depth must be a non-negative integer")
    if not isinstance(max_steps, int) or isinstance(max_steps, bool) or max_steps < 1:
        raise ValueError("max_steps must be a positive integer")

    def provenance(value):
        if (not isinstance(value, dict)
                or not isinstance(value.get("source"), str) or not value["source"]
                or value.get("trust") not in {"trusted", "untrusted"}):
            raise ValueError("provenance needs source and explicit trust")
        return copy_json(value, field="guardrail provenance JSON")

    if not isinstance(input_value, dict) or "content" not in input_value:
        raise ValueError("input needs content and provenance")
    initial = {
        "content": copy_json(input_value["content"], field="guarded input JSON"),
        "provenance": provenance(input_value.get("provenance")),
    }
    cancelled_value = request.get("cancelled", False)

    def cancelled():
        return bool(cancelled_value() if callable(cancelled_value) else cancelled_value)

    records = []
    previous_hash = "0" * 64

    def audit(event, data):
        nonlocal previous_hash
        try:
            sanitized = redactor.redact(copy_json(data, field="audit data JSON"))
            sanitized = copy_json(sanitized, field="redacted audit JSON")
        except HarnessFailure:
            raise
        except Exception as error:
            raise RedactionFailure(error) from error
        base = {
            "sequence": len(records),
            "event": event,
            "data": sanitized,
            "previous_hash": previous_hash,
        }
        canonical = json.dumps(base, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        record = {**base, "hash": hashlib.sha256(canonical.encode("utf-8")).hexdigest()}
        try:
            audit_sink.append(deepcopy(record))
        except HarnessFailure:
            raise
        except Exception as error:
            raise AuditFailure(error) from error
        records.append(record)
        previous_hash = record["hash"]

    def stop(status, failure=None, *, event=None, data=None, pending=None, output=None):
        if event is not None:
            audit(event, {} if data is None else data)
        return GuardedResult(status, output, failure, records, pending)

    def cancel_runtime():
        runtime.cancel()

    def safe_error_message(error):
        try:
            value = redactor.redact(str(error))
            return value if isinstance(value, str) else "[REDACTED ERROR]"
        except HarnessFailure:
            raise
        except Exception:
            return "[REDACTED ERROR]"

    def apply_policy(context):
        original_provenance = deepcopy(context["provenance"])
        original_kind = context["kind"]
        decision = policy_engine.evaluate(deepcopy(context))
        if getattr(decision, "action", None) not in {"allow", "deny", "transform"}:
            return None, {"type": "policy_failure", "reason": "invalid_decision"}
        if decision.action == "deny":
            return None, {"type": "policy_denied", "reasons": list(decision.reasons)}
        result = deepcopy(decision.context)
        if not isinstance(result, dict):
            return None, {"type": "policy_failure", "reason": "invalid_context"}
        result["kind"] = original_kind
        result["provenance"] = original_provenance
        return result, None

    try:
        if cancelled():
            cancel_runtime()
            return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
        input_context, failure = apply_policy({
            "kind": "request_input", "content": initial["content"],
            "provenance": initial["provenance"], "delegation_depth": 0,
        })
        if failure:
            cancel_runtime()
            return stop("denied", failure, event="policy.denied", data=failure)
        runtime_input = {
            "content": deepcopy(input_context.get("content")),
            "provenance": deepcopy(initial["provenance"]),
        }
        audit("request.accepted", input_context)
        output = None
        steps = 0
        for raw_event in runtime.events(deepcopy(runtime_input)):
            if cancelled():
                cancel_runtime()
                return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
            steps += 1
            if steps > max_steps:
                cancel_runtime()
                failure = {"type": "step_budget", "max_steps": max_steps}
                return stop("denied", failure, event="budget.denied", data=failure)
            event = copy_json(raw_event, field="runtime event JSON")
            if not isinstance(event, dict) or event.get("kind") not in {
                "model_input", "tool_call", "tool_output", "memory_read", "output"
            }:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            event_provenance = provenance(event.get("provenance"))
            depth = event.get("delegation_depth")
            if not isinstance(depth, int) or isinstance(depth, bool) or depth < 0:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            if depth > max_depth:
                cancel_runtime()
                failure = {"type": "delegation_depth", "max_depth": max_depth}
                return stop("denied", failure, event="delegation.denied", data=failure)
            context = {"kind": event["kind"], "provenance": event_provenance,
                       "delegation_depth": depth}
            field = "action" if event["kind"] == "tool_call" else "content"
            if field not in event:
                cancel_runtime()
                return stop("failed", {"type": "malformed_runtime_event"},
                            event="runtime.failed", data={"type": "malformed_runtime_event"})
            context[field] = deepcopy(event[field])
            checked, failure = apply_policy(context)
            if failure:
                cancel_runtime()
                return stop("denied", failure, event="policy.denied", data=failure)
            event[field] = deepcopy(checked.get(field))
            event["provenance"] = event_provenance
            if event["kind"] == "tool_call":
                try:
                    event["action"] = redactor.redact(deepcopy(event["action"]))
                    event["action"] = copy_json(
                        event["action"], field="redacted executable action JSON"
                    )
                except HarnessFailure:
                    raise
                except Exception as error:
                    raise RedactionFailure(error) from error
                if approval_gate is None:
                    cancel_runtime()
                    failure = {"type": "approval_failure", "reason": "missing_gate"}
                    return stop("denied", failure, event="tool.denied", data=failure)
                outcome = approval_gate.classify(
                    deepcopy(event["action"]), set(capabilities), deepcopy(event_provenance)
                )
                if cancelled():
                    cancel_runtime()
                    return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
                outcome_name = type(outcome).__name__
                if outcome_name == "DeniedAction":
                    cancel_runtime()
                    failure = {"type": "approval_denied", "reason": outcome.reason}
                    return stop("denied", failure, event="tool.denied", data=failure)
                if outcome_name == "ApprovalRequest":
                    audit("tool.awaiting_approval", {"digest": outcome.digest})
                    return GuardedResult("awaiting_approval", audit_records=records,
                                         pending_approval=outcome)
                if outcome_name != "ApprovedAction":
                    cancel_runtime()
                    failure = {"type": "approval_failure", "reason": "invalid_result"}
                    return stop("denied", failure, event="tool.denied", data=failure)
                event["action"] = deepcopy(outcome.action)
                audit("tool.approved", event)
                if cancelled():
                    cancel_runtime()
                    return stop("cancelled", {"type": "cancelled"}, event="run.cancelled")
                runtime.commit(deepcopy(event))
                audit("tool.committed", event)
            else:
                audit(event["kind"], event)
                if event["kind"] == "output":
                    try:
                        output = redactor.redact(deepcopy(event["content"]))
                        output = copy_json(output, field="redacted output JSON")
                    except HarnessFailure:
                        raise
                    except Exception as error:
                        raise RedactionFailure(error) from error
        audit("run.completed", {"steps": steps})
        return GuardedResult("completed", output, audit_records=records)
    except HarnessFailure:
        raise
    except AuditFailure as wrapped:
        cancel_runtime()
        error = wrapped.error
        return GuardedResult("failed", failure={"type": "audit_failure",
            "error_type": type(error).__name__, "message": safe_error_message(error)},
            audit_records=records)
    except RedactionFailure as wrapped:
        cancel_runtime()
        error = wrapped.error
        failure = {"type": "redaction_failure",
                   "error_type": type(error).__name__, "message": "redaction failed"}
        try:
            audit("redaction.failed", failure)
        except (AuditFailure, RedactionFailure):
            pass
        return GuardedResult("failed", failure=failure, audit_records=records)
    except Exception as error:
        cancel_runtime()
        failure = {"type": "runtime_failure", "error_type": type(error).__name__,
                   "message": safe_error_message(error)}
        try:
            audit("runtime.failed", failure)
        except AuditFailure as audit_wrapped:
            audit_error = audit_wrapped.error
            return GuardedResult("failed", failure={"type": "audit_failure",
                "error_type": type(audit_error).__name__,
                "message": safe_error_message(audit_error)}, audit_records=records)
        except RedactionFailure:
            return GuardedResult("failed", failure={"type": "redaction_failure",
                "error_type": "RedactionFailure", "message": "redaction failed"},
                audit_records=records)
        return GuardedResult("failed", failure=failure, audit_records=records)

class _ManualReLU(nn.Module):
    def forward(self, x):
        return x.clamp(min=0)

class MixtureOfExperts(nn.Module):
    def __init__(self, d_model, d_ff, num_experts, top_k=2):
        super().__init__()
        self.top_k = top_k
        self.router = nn.Linear(d_model, num_experts)
        self.experts = nn.ModuleList([
            nn.Sequential(nn.Linear(d_model, d_ff), _ManualReLU(), nn.Linear(d_ff, d_model))
            for _ in range(num_experts)
        ])

    def forward(self, x):
        orig_shape = x.shape
        if x.dim() == 3:
            B, S, D = x.shape
            x_flat = x.reshape(-1, D)
        else:
            x_flat = x
        logits = self.router(x_flat)
        top_vals, top_idx = logits.topk(self.top_k, dim=-1)
        weights = torch.softmax(top_vals, dim=-1)
        output = torch.zeros_like(x_flat)
        for k in range(self.top_k):
            for e in range(len(self.experts)):
                mask = (top_idx[:, k] == e)
                if mask.any():
                    output[mask] += weights[mask, k:k+1] * self.experts[e](x_flat[mask])
        return output.reshape(orig_shape)

def moe_capacity_dispatch(x, expert_indices, expert_weights, experts, capacity):
    if x.ndim != 2 or expert_indices.ndim != 2 or expert_weights.shape != expert_indices.shape:
        raise ValueError("x and route tensors have invalid shapes")
    if expert_indices.shape[0] != x.shape[0] or expert_indices.dtype != torch.long:
        raise ValueError("route tensors must align with tokens and indices must be long")
    if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 0 or not experts:
        raise ValueError("capacity and experts are invalid")
    if expert_indices.numel() and (int(expert_indices.min()) < 0 or int(expert_indices.max()) >= len(experts)):
        raise ValueError("expert index out of range")
    loads = [0 for _ in experts]
    routes = [[] for _ in experts]
    for token in range(expert_indices.shape[0]):
        for slot in range(expert_indices.shape[1]):
            expert_id = int(expert_indices[token, slot])
            if loads[expert_id] < capacity:
                routes[expert_id].append((token, slot))
                loads[expert_id] += 1
    output = torch.zeros_like(x)
    for expert_id, accepted in enumerate(routes):
        if not accepted:
            continue
        token_ids = torch.tensor([token for token, _ in accepted], device=x.device)
        slot_ids = torch.tensor([slot for _, slot in accepted], device=x.device)
        expert_output = experts[expert_id](x.index_select(0, token_ids))
        route_weights = expert_weights[token_ids, slot_ids].to(expert_output.dtype).unsqueeze(-1)
        output.index_add_(0, token_ids, expert_output * route_weights)
    accepted_count = sum(loads)
    return output, {"accepted": accepted_count, "dropped": expert_indices.numel() - accepted_count, "loads": loads}

import torch


def ppo_clipped_policy_loss(
    logprobs, old_logprobs, advantages, mask, clip_eps=0.2, dual_clip=None
):
    shapes = (logprobs.shape, old_logprobs.shape, advantages.shape, mask.shape)
    if len(set(shapes)) != 1:
        raise ValueError(f"all tensors must share a shape, got {shapes}")
    if clip_eps <= 0:
        raise ValueError(f"clip_eps must be positive, got {clip_eps}")
    if dual_clip is not None and dual_clip <= 1.0:
        raise ValueError(f"dual_clip must be greater than 1.0, got {dual_clip}")

    keep = mask.to(logprobs.dtype)
    denominator = keep.sum()
    if denominator == 0:
        return torch.zeros((), dtype=logprobs.dtype, device=logprobs.device)

    ratio = torch.exp(logprobs - old_logprobs)
    unclipped = ratio * advantages
    clipped = ratio.clamp(1.0 - clip_eps, 1.0 + clip_eps) * advantages
    per_token = -torch.min(unclipped, clipped)

    if dual_clip is not None:
        bounded = torch.min(per_token, -dual_clip * advantages)
        per_token = torch.where(advantages < 0, bounded, per_token)

    return (per_token * keep).sum() / denominator

import torch


def rollout_batch_assembly(prompt_ids, generation_ids, advantages, pad_id=0):
    batch_size = len(prompt_ids)
    if batch_size == 0:
        raise ValueError("the batch must hold at least one response")
    if len(generation_ids) != batch_size:
        raise ValueError(
            f"prompt_ids has {batch_size} rows but generation_ids has {len(generation_ids)}"
        )
    if advantages.ndim != 1 or advantages.shape[0] != batch_size:
        raise ValueError(
            f"advantages must have shape ({batch_size},), got {tuple(advantages.shape)}"
        )

    device = advantages.device
    prompt_lens = torch.tensor([len(p) for p in prompt_ids], device=device)
    gen_lens = torch.tensor([len(g) for g in generation_ids], device=device)
    total_lens = prompt_lens + gen_lens
    width = int(total_lens.max())

    input_ids = torch.full((batch_size, width), pad_id, dtype=torch.long, device=device)
    for row, (prompt, generation) in enumerate(zip(prompt_ids, generation_ids)):
        tokens = list(prompt) + list(generation)
        if tokens:
            input_ids[row, : len(tokens)] = torch.tensor(
                tokens, dtype=torch.long, device=device
            )

    positions = torch.arange(width, device=device).unsqueeze(0)
    mask = (positions >= prompt_lens.unsqueeze(-1)) & (positions < total_lens.unsqueeze(-1))
    token_advantages = advantages.unsqueeze(-1) * mask.to(advantages.dtype)

    return {
        "input_ids": input_ids,
        "mask": mask,
        "token_advantages": token_advantages,
        "lengths": gen_lens,
    }

def speculative_decode(target_probs, draft_probs, draft_tokens):
    K = len(draft_tokens)
    accepted = []
    for i in range(K):
        t = draft_tokens[i].item()
        ratio = target_probs[i, t] / max(draft_probs[i, t].item(), 1e-10)
        if torch.rand(1).item() < min(1.0, ratio.item()):
            accepted.append(t)
        else:
            adjusted = torch.clamp(target_probs[i] - draft_probs[i], min=0)
            s = adjusted.sum()
            if s > 0:
                adjusted = adjusted / s
            else:
                adjusted = torch.ones_like(adjusted) / adjusted.shape[0]
            accepted.append(torch.multinomial(adjusted, 1).item())
            return accepted
    return accepted

class TensorParallelMLP(nn.Module):
    def __init__(self, d_model, d_ff, world_size):
        super().__init__()
        self.world_size = world_size
        shard_size = d_ff // world_size
        # Column-parallel: W1 shards (d_model, shard_size) each
        self.w1_shards = nn.ParameterList([
            nn.Parameter(torch.randn(d_model, shard_size) * (2 / d_model) ** 0.5)
            for _ in range(world_size)
        ])
        # Row-parallel: W2 shards (shard_size, d_model) each
        self.w2_shards = nn.ParameterList([
            nn.Parameter(torch.randn(shard_size, d_model) * (2 / d_ff) ** 0.5)
            for _ in range(world_size)
        ])

    def forward(self, x):
        # Column-parallel forward + row-parallel + all-reduce (sum)
        output = None
        for w1, w2 in zip(self.w1_shards, self.w2_shards):
            z = x @ w1
            h = z * 0.5 * (1.0 + torch.erf(z / (2.0 ** 0.5)))  # GELU
            partial = h @ w2                        # (B, d_model)
            output = partial if output is None else output + partial
        return output

import torch


def vineppo_mc_value(rollout_rewards, final_reward):
    if rollout_rewards.ndim != 2:
        raise ValueError(
            f"rollout_rewards must be two-dimensional, got {tuple(rollout_rewards.shape)}"
        )
    states, continuations = rollout_rewards.shape
    if states == 0 or continuations == 0:
        raise ValueError(
            f"need at least one state and one continuation, got {tuple(rollout_rewards.shape)}"
        )

    values = rollout_rewards.mean(dim=-1)
    bootstrap = final_reward.reshape(1).to(values.dtype)
    next_value = torch.cat([values[1:], bootstrap])
    return values, next_value - values
